#![cfg(feature = "viewer")]
use bw_rust::{
    ObjectGraph, ObjectId,
    first_mission::{Input, Session},
    lua50::Value,
    parse_objects,
};
/// Input-driven continuation of the original mission through the staff-bearer cutscene and control return.
#[test]
#[ignore = "private assets and ambush recording generated by first_mission_squad"]
fn original_route_completes_staff_bearer_cutscene_and_returns_player_control() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let data = root.join("local/extracted/files/Data/CompoundFiles");
    let mut graph = ObjectGraph::default();
    for file in ["SP_0.1_Level.xml", "SP_0.1_Level_preload.xml"] {
        graph
            .merge(parse_objects(&std::fs::read_to_string(data.join(file)).unwrap()).unwrap())
            .unwrap();
    }
    let mut s = Session::load(
        root,
        &graph,
        &std::fs::read(data.join("SP_0.1_Level.res")).unwrap(),
    )
    .unwrap();
    let inputs: Vec<Input> = serde_json::from_slice(
        &std::fs::read(root.join("local/analysis/ambush-complete-inputs.json")).unwrap(),
    )
    .unwrap();
    let initial_player = s.program.host.world.player;
    let initial_seed = s.program.host.world.waypoint_rand.state();
    let initial_grunt04 = s.program.host.positions[&ObjectId(550030841)];
    s.begin_recording();
    for input in inputs {
        s.tick(1. / 60., input).unwrap();
    }
    let start = s.program.host.positions[&s.program.host.world.player.unwrap()];
    println!(
        "STAFF_START player={start:?} markers={:?}",
        s.markers
            .iter()
            .filter_map(|m| m.position(&s.program.host).unwrap().map(|p| (m.id, p)))
            .collect::<Vec<_>>()
    );
    let mut transferred = false;
    let mut trench_shot_recording_len = None;
    for frame in 0..3600 {
        let h = &s.program.host;
        let before_frame = h.frame;
        let before_player = h.world.player;
        let before_cut = h.world.player_view.as_ref().unwrap().cut_revision;
        let hidden = h.world.frozen && h.world.cameras.as_ref().unwrap().black_alpha == 1.;
        let before_positions = h.positions.clone();
        let p = h.positions[&h.world.player.unwrap()];
        let aim = h.world.player_aim.unwrap();
        let target = s
            .markers
            .iter()
            .filter_map(|m| m.position(h).unwrap())
            .min_by(|a, b| {
                let d = |v: &[f32; 3]| (v[0] - p[0]).hypot(v[2] - p[2]);
                d(a).total_cmp(&d(b))
            })
            .unwrap_or(p);
        let dx = (target[0] - p[0]) as f64;
        let dz = (target[2] - p[2]) as f64;
        let yaw = (dx.atan2(dz) - aim[0].atan2(aim[2]) + std::f64::consts::PI)
            .rem_euclid(std::f64::consts::TAU)
            - std::f64::consts::PI;
        if let Err(e) = s.tick(
            1. / 60.,
            Input {
                movement: [
                    0.,
                    if dx.hypot(dz) > 1. && yaw.abs() < 0.15 {
                        1.
                    } else {
                        0.
                    },
                ],
                look: [yaw.clamp(-0.05, 0.05), 0.],
                ..Default::default()
            },
        ) {
            assert_eq!(s.program.host.frame, before_frame);
            assert_eq!(s.program.host.world.player, before_player);
            assert_eq!(s.program.host.positions, before_positions);
            panic!("Staff cutscene blocked transactionally at frame {frame}: {e}");
        }
        if s.program.host.world.player != before_player {
            assert!(hidden);
            assert_eq!(
                s.program
                    .host
                    .world
                    .player_view
                    .as_ref()
                    .unwrap()
                    .cut_revision,
                before_cut
            );
            assert_eq!(s.program.host.world.player, Some(ObjectId(550035312)));
            transferred = true;
        }
        if trench_shot_recording_len.is_none()
            && s.program.vm.globals.get("cutsceneStaffBearerBegin") == Some(&Value::Number(1.))
            && (s.program.host.positions[&ObjectId(550030841)][2] - (initial_grunt04[2] - 1.0))
                .abs()
                < 1e-4
            && s.program.host.world.cameras.as_ref().unwrap().black_alpha == 0.0
        {
            trench_shot_recording_len = Some(s.program.host.frame as usize - 1 + 60);
        }
        if s.program.vm.globals.get("cutsceneStaffBearerBegin") == Some(&Value::Number(2.))
            && !s.program.host.world.frozen
        {
            let h = &s.program.host;
            let w = &h.world;
            assert!(transferred);
            assert_eq!(w.player, Some(ObjectId(550035312)));
            assert!(w.roster.contains(&ObjectId(550035312)));
            assert_eq!(
                w.cameras.as_ref().unwrap().chase_target(),
                Some(ObjectId(550035312))
            );
            assert_eq!(w.objectives[&ObjectId(550041656)], (true, true));
            assert_eq!(w.objectives[&ObjectId(550035435)], (true, false));
            let visible_markers: Vec<_> = s
                .markers
                .iter()
                .filter_map(|m| m.position(h).unwrap().map(|pos| (m.id, pos)))
                .collect();
            assert!(
                !visible_markers
                    .iter()
                    .any(|(id, _)| *id == ObjectId(550041658))
            );
            assert!(
                visible_markers
                    .iter()
                    .any(|(id, _)| *id == ObjectId(550035437))
            );
            let grunt04 = h.positions[&ObjectId(550030841)];
            assert!((grunt04[0] - initial_grunt04[0]).abs() < 1e-4);
            assert!((grunt04[2] - (initial_grunt04[2] - 1.0)).abs() < 1e-4);
            assert!(matches!(
                w.following[&ObjectId(550030859)].node,
                ObjectId(550030756) | ObjectId(550031649)
            ));
            assert_eq!(w.following[&ObjectId(550030356)].node, ObjectId(550031659));
            let new_player_pos = h.positions[&ObjectId(550035312)];
            println!(
                "ORIGINAL_STAFF_CUTSCENE_COMPLETE input_frames={frame} time={:.2} player={:?} pos={new_player_pos:?} markers={visible_markers:?} following={}",
                h.time,
                w.player,
                w.following.len(),
            );
            let recording = s.take_recording().unwrap();
            std::fs::write(
                root.join("local/analysis/staff-complete-inputs.json"),
                serde_json::to_vec(&recording).unwrap(),
            )
            .unwrap();
            if let Some(n) = trench_shot_recording_len
                && n < recording.len()
            {
                std::fs::write(
                    root.join("local/analysis/staff-trench-shot-inputs.json"),
                    serde_json::to_vec(&recording[..n]).unwrap(),
                )
                .unwrap();
            }
            s.begin_recording();
            let mut last_markers = Vec::new();
            let mut planned_target = None;
            let mut route_points = std::collections::VecDeque::<[f64; 2]>::new();
            let mut last_plan_frame = 0;
            let mut last_progress_pos = [0.0f32; 3];
            let mut last_progress_frame = 0;
            for post_frame in 0..18000 {
                let h = &s.program.host;
                let before_frame = h.frame;
                let before_positions = h.positions.clone();
                let player_id = h.world.player.unwrap();
                let p = h.positions[&player_id];
                if (p[0] - last_progress_pos[0]).hypot(p[2] - last_progress_pos[2]) > 0.3
                    || h.world.frozen
                {
                    last_progress_pos = p;
                    last_progress_frame = post_frame;
                }
                let aim = h.world.player_aim.unwrap();
                let current_markers: Vec<_> = s
                    .markers
                    .iter()
                    .filter_map(|m| m.position(h).unwrap().map(|pos| (m.id, pos)))
                    .collect();
                if current_markers != last_markers {
                    println!(
                        "POST_STAFF_MARKERS post_frame={post_frame} pos={p:?} frozen={} markers={current_markers:?}",
                        h.world.frozen
                    );
                    last_markers = current_markers;
                }
                let goal = s
                    .markers
                    .iter()
                    .filter_map(|m| m.position(h).unwrap())
                    .min_by(|a, b| {
                        let d = |v: &[f32; 3]| (v[0] - p[0]).hypot(v[2] - p[2]);
                        d(a).total_cmp(&d(b))
                    })
                    .unwrap_or(p);
                let goal_2d = [goal[0] as f64, goal[2] as f64];
                let stuck = post_frame - last_progress_frame >= 45
                    && post_frame - last_plan_frame >= 45
                    && (goal[0] - p[0]).hypot(goal[2] - p[2]) > 2.0;
                let enemy_at_goal = h
                    .world
                    .units
                    .iter()
                    .find(|(id, u)| {
                        **id != player_id
                            && u.active == Some(true)
                            && u.health > 0.0
                            && u.army != h.world.units[&player_id].army
                            && (h.positions[id][0] as f64 - goal_2d[0])
                                .hypot(h.positions[id][2] as f64 - goal_2d[1])
                                < 5.0
                    })
                    .map(|(id, _)| *id);
                let goal_radius = if let Some(enemy_id) = enemy_at_goal {
                    h.world.bodies[&enemy_id].radius + 2.5
                } else {
                    2.0
                };
                if h.world.frozen {
                    planned_target = None;
                    route_points.clear();
                } else if planned_target != Some(goal_2d) || stuck {
                    let scene = h.world.collision.as_ref().unwrap();
                    let others: Vec<_> = h
                        .world
                        .units
                        .iter()
                        .filter(|(id, u)| {
                            **id != player_id
                                && u.active == Some(true)
                                && u.health > 0.0
                                && !h.world.non_ground_units.contains(id)
                        })
                        .map(|(id, _)| bw_rust::unit_collision::Other {
                            position: h.positions[id],
                            body: h.world.bodies[id],
                        })
                        .collect();
                    let plan = bw_rust::navigation::plan(
                        scene,
                        p,
                        goal_2d,
                        goal_radius,
                        bw_rust::unit_collision::Body::INFANTRY,
                        &others,
                        bw_rust::navigation::Limits {
                            expansions: 16384,
                            probes: 524288,
                            extent: 512,
                        },
                    )
                    .unwrap();
                    println!(
                        "PLAN post_frame={post_frame} from={p:?} to={goal_2d:?} radius={goal_radius} status={:?} pts={} exp={} probes={}",
                        plan.status,
                        plan.points.len(),
                        plan.expanded,
                        plan.probes
                    );
                    route_points = plan.points.into();
                    planned_target = Some(goal_2d);
                    last_plan_frame = post_frame;
                    last_progress_frame = post_frame;
                }
                let _ = last_plan_frame;
                while let Some(&pt) = route_points.front() {
                    if (pt[0] - p[0] as f64).hypot(pt[1] - p[2] as f64) < 1.2 {
                        route_points.pop_front();
                    } else {
                        break;
                    }
                }
                let dist_to_goal = (goal_2d[0] - p[0] as f64).hypot(goal_2d[1] - p[2] as f64);
                let in_firing_stand = enemy_at_goal.is_some() && dist_to_goal <= goal_radius + 1.0;
                let firing_at_goal = enemy_at_goal.is_some() && dist_to_goal <= 25.0;
                let enemy_ahead = h.world.units.iter().any(|(id, u)| {
                    *id != player_id
                        && u.active == Some(true)
                        && u.health > 0.0
                        && u.army != h.world.units[&player_id].army
                        && {
                            let ep = h.positions[id];
                            let ex = (ep[0] - p[0]) as f64;
                            let ez = (ep[2] - p[2]) as f64;
                            let d = ex.hypot(ez);
                            d <= 28.0 && d > 0.1 && (ex * aim[0] + ez * aim[2]) / d > 0.85
                        }
                });
                let next_pt = if in_firing_stand {
                    goal_2d
                } else {
                    route_points.front().copied().unwrap_or(goal_2d)
                };
                let dx = next_pt[0] - p[0] as f64;
                let dz = next_pt[1] - p[2] as f64;
                let yaw = (dx.atan2(dz) - aim[0].atan2(aim[2]) + std::f64::consts::PI)
                    .rem_euclid(std::f64::consts::TAU)
                    - std::f64::consts::PI;
                let pitch_delta = if let Some(enemy_id) = enemy_at_goal
                    && firing_at_goal
                {
                    let scene = h.world.collision.as_ref().unwrap();
                    let from = scene
                        .world_point(p, (h.world.bodies[&player_id].height * 0.65) as f32)
                        .unwrap();
                    let to = scene
                        .world_point(
                            h.positions[&enemy_id],
                            (h.world.bodies[&enemy_id].height * 0.65) as f32,
                        )
                        .unwrap();
                    let dy = (to[1] - from[1]) as f64;
                    let horiz = ((to[0] - from[0]) as f64).hypot((to[2] - from[2]) as f64);
                    let desired_pitch = dy.atan2(horiz);
                    let current_pitch = aim[1].clamp(-1.0, 1.0).asin();
                    (desired_pitch - current_pitch).clamp(-0.08, 0.08)
                } else {
                    (0.0 - aim[1].clamp(-1.0, 1.0).asin()).clamp(-0.08, 0.08)
                };
                if in_firing_stand {
                    last_progress_frame = post_frame;
                }
                if post_frame >= 4360 && post_frame % 100 == 0 {
                    println!(
                        "BS_DIAG post_frame={post_frame} pos={p:?} dist={dist_to_goal:.2} stand={in_firing_stand} firing={firing_at_goal} yaw={yaw:.3} player_hp={} bs_hp={:?} fired={} hits={} last_shot={:?}",
                        h.world.units[&player_id].health,
                        h.world.units.get(&ObjectId(550031178)).map(|u| (
                            u.health,
                            u.invulnerable,
                            u.active
                        )),
                        s.combat.fired,
                        s.combat.hits,
                        s.combat
                            .shots
                            .last()
                            .map(|sh| (sh.shooter, sh.hit, sh.damage, sh.from, sh.to)),
                    );
                }
                let should_fire = (firing_at_goal && yaw.abs() < 0.25) || enemy_ahead;
                if let Err(e) = s.tick(
                    1. / 60.,
                    Input {
                        movement: [
                            0.,
                            if !in_firing_stand && dx.hypot(dz) > 0.5 && yaw.abs() < 0.25 {
                                1.
                            } else {
                                0.
                            },
                        ],
                        look: [yaw.clamp(-0.08, 0.08), pitch_delta],
                        fire: should_fire,
                        lock: should_fire,
                        ..Default::default()
                    },
                ) {
                    assert_eq!(s.program.host.frame, before_frame);
                    assert_eq!(s.program.host.positions, before_positions);
                    println!(
                        "POST_STAFF_BOUNDARY post_frame={post_frame} pos={p:?} err={e}; transactional rollback verified"
                    );
                    panic!("Next boundary: {e}");
                }
                if s.program.vm.globals.get("JumpOverLedgeDone") == Some(&Value::Number(1.0))
                    && !s.program.host.world.frozen
                {
                    let mut tower_recording = recording.clone();
                    tower_recording.extend(s.take_recording().unwrap());
                    std::fs::write(
                        root.join("local/analysis/first-tower-inputs.json"),
                        serde_json::to_vec(&tower_recording).unwrap(),
                    )
                    .unwrap();
                    println!(
                        "TOWER_CUTSCENE_COMPLETE post_frame={post_frame} total_inputs={} player={:?} pos={:?}",
                        tower_recording.len(),
                        s.program.host.world.player,
                        s.program.host.positions[&s.program.host.world.player.unwrap()],
                    );
                    break;
                }
            }
            println!(
                "POST_STAFF_END pos={:?} frozen={}",
                s.program.host.positions[&s.program.host.world.player.unwrap()],
                s.program.host.world.frozen
            );
            s.restart();
            assert_eq!(s.program.host.frame, 1);
            assert_eq!(s.program.host.world.player, initial_player);
            assert_eq!(s.program.host.world.waypoint_rand.state(), initial_seed);
            assert_eq!(
                s.program.host.positions[&ObjectId(550030841)],
                initial_grunt04
            );
            assert!(s.program.host.world.following.is_empty());
            return;
        }
    }
    panic!(
        "Staff route failed to complete within bounded simulation: position={:?} trigger={:?}",
        s.program.host.positions[&s.program.host.world.player.unwrap()],
        s.program.vm.globals.get("cutsceneStaffBearerBegin")
    );
}

#[test]
#[ignore = "Requires local extracted BW2 dump in local/extracted"]
fn first_mission_reaches_victory_and_defeat() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let data = root.join("local/extracted/files/Data/CompoundFiles");
    let mut graph = ObjectGraph::default();
    for file in ["SP_0.1_Level.xml", "SP_0.1_Level_preload.xml"] {
        graph
            .merge(parse_objects(&std::fs::read_to_string(data.join(file)).unwrap()).unwrap())
            .unwrap();
    }
    let mut s = Session::load(
        root,
        &graph,
        &std::fs::read(data.join("SP_0.1_Level.res")).unwrap(),
    )
    .unwrap();
    let mut prefix: Vec<Input> = serde_json::from_slice(
        &std::fs::read(root.join("local/analysis/first-tower-inputs.json")).unwrap(),
    )
    .unwrap();
    for input in &prefix {
        s.tick(1.0 / 60.0, *input).unwrap();
    }
    if s.program.vm.globals.get("JumpOverLedgeDone") != Some(&Value::Number(1.0))
        || s.program.host.world.frozen
        || s.program.host.world.units[&s.program.host.world.player.unwrap()].health < 600.0
    {
        s = Session::load(
            root,
            &graph,
            &std::fs::read(data.join("SP_0.1_Level.res")).unwrap(),
        )
        .unwrap();
        prefix.truncate(13_100);
        for input in &prefix {
            s.tick(1.0 / 60.0, *input).unwrap();
        }
        let p0 = s.program.host.positions[&s.program.host.world.player.unwrap()];
        println!(
            "RE-RECORDING BATTLESTATION FROM 13100: pos=({:.1}, {:.1}) hp={:.0}",
            p0[0],
            p0[2],
            s.program.host.world.units[&s.program.host.world.player.unwrap()].health,
        );
        let bs_id = ObjectId(550031178);
        let mut bs_pause = 0u32;
        let mut bs_planned = None;
        let mut bs_route = std::collections::VecDeque::<[f64; 2]>::new();
        let mut bs_last_plan = 0usize;
        for step in 0..8_000 {
            let player = s.program.host.world.player.unwrap();
            let pos = s.program.host.positions[&player];
            let paused = s
                .program
                .host
                .world
                .tutorial
                .as_ref()
                .is_some_and(|t| t.paused);
            if paused {
                bs_pause += 1;
            } else {
                bs_pause = 0;
            }
            let confirm = paused && bs_pause >= 125 && bs_pause.is_multiple_of(4);
            let bs_unit = &s.program.host.world.units[&bs_id];
            let bs_alive = bs_unit.active == Some(true) && bs_unit.health > 0.0;
            let bs_invuln = bs_unit.invulnerable;
            let bs_pos = s.program.host.positions[&bs_id];
            let (goal, goal_radius) = if bs_invuln {
                ([95.0, 495.0], 2.0)
            } else {
                (
                    [bs_pos[0] as f64, bs_pos[2] as f64],
                    s.program.host.world.bodies[&bs_id].radius + 2.5,
                )
            };
            let dist_to_goal = (goal[0] - pos[0] as f64).hypot(goal[1] - pos[2] as f64);
            let in_stand = !bs_invuln && dist_to_goal <= goal_radius + 1.0;
            if !paused
                && !s.program.host.world.frozen
                && !in_stand
                && dist_to_goal > goal_radius
                && (bs_planned != Some(goal) || step - bs_last_plan >= 90)
            {
                let h = &s.program.host;
                let scene = h.world.collision.as_ref().unwrap();
                let others: Vec<_> = h
                    .world
                    .units
                    .iter()
                    .filter(|(id, u)| {
                        **id != player
                            && !h.world.roster.contains(id)
                            && u.active == Some(true)
                            && u.health > 0.0
                            && !h.world.non_ground_units.contains(id)
                    })
                    .map(|(id, _)| bw_rust::unit_collision::Other {
                        position: h.positions[id],
                        body: h.world.bodies[id],
                    })
                    .collect();
                let plan = bw_rust::navigation::plan(
                    scene,
                    pos,
                    goal,
                    goal_radius,
                    bw_rust::unit_collision::Body::INFANTRY,
                    &others,
                    bw_rust::navigation::Limits {
                        expansions: 16384,
                        probes: 524288,
                        extent: 512,
                    },
                )
                .unwrap();
                bs_route = plan.points.into();
                bs_planned = Some(goal);
                bs_last_plan = step;
            }
            while let Some(&pt) = bs_route.front() {
                if (pt[0] - pos[0] as f64).hypot(pt[1] - pos[2] as f64) < 1.2 {
                    bs_route.pop_front();
                } else {
                    break;
                }
            }
            let next_pt = if in_stand {
                goal
            } else {
                bs_route.front().copied().unwrap_or(goal)
            };
            let mut input = Input {
                confirm,
                ..Input::default()
            };
            if !paused && !s.program.host.world.frozen {
                let h = &s.program.host;
                let aim = h.world.player_aim.unwrap();
                let current_yaw = aim[0].atan2(aim[2]);
                let dx = next_pt[0] - pos[0] as f64;
                let dz = next_pt[1] - pos[2] as f64;
                let desired_yaw = dx.atan2(dz);
                let mut diff = (desired_yaw - current_yaw + std::f64::consts::PI)
                    .rem_euclid(std::f64::consts::TAU)
                    - std::f64::consts::PI;
                diff = diff.clamp(-0.08, 0.08);
                let firing = bs_alive && !bs_invuln && dist_to_goal <= 25.0;
                let pitch_delta = if firing {
                    let scene = h.world.collision.as_ref().unwrap();
                    let from = scene
                        .world_point(pos, (h.world.bodies[&player].height * 0.65) as f32)
                        .unwrap();
                    let to = scene
                        .world_point(bs_pos, (h.world.bodies[&bs_id].height * 0.65) as f32)
                        .unwrap();
                    let dy = (to[1] - from[1]) as f64;
                    let horiz = ((to[0] - from[0]) as f64).hypot((to[2] - from[2]) as f64);
                    let desired_pitch = dy.atan2(horiz);
                    let current_pitch = aim[1].clamp(-1.0, 1.0).asin();
                    (desired_pitch - current_pitch).clamp(-0.08, 0.08)
                } else {
                    (0.0 - aim[1].clamp(-1.0, 1.0).asin()).clamp(-0.08, 0.08)
                };
                input.look = [diff, pitch_delta];
                if !in_stand && dx.hypot(dz) > 0.5 && diff.abs() < 0.25 {
                    input.movement = [0.0, 1.0];
                }
                if firing && diff.abs() < 0.25 {
                    input.lock = true;
                    input.fire = true;
                }
            }
            s.tick(1.0 / 60.0, input).unwrap();
            prefix.push(input);
            if step % 300 == 0 {
                println!(
                    "BS_STEP step={step} pos=({:.1}, {:.1}) hp={:.0} bs_hp={:.0} invuln={bs_invuln} paused={paused} frozen={}",
                    pos[0],
                    pos[2],
                    s.program.host.world.units[&player].health,
                    s.program.host.world.units[&bs_id].health,
                    s.program.host.world.frozen
                );
            }
            if s.program.vm.globals.get("JumpOverLedgeDone") == Some(&Value::Number(1.0))
                && !s.program.host.world.frozen
            {
                println!(
                    "TOWER CUTSCENE COMPLETE at step={step} total={} hp={:.0}",
                    prefix.len(),
                    s.program.host.world.units[&s.program.host.world.player.unwrap()].health
                );
                std::fs::write(
                    root.join("local/analysis/first-tower-inputs.json"),
                    serde_json::to_vec(&prefix).unwrap(),
                )
                .unwrap();
                break;
            }
        }
    }
    assert_eq!(
        s.program.vm.globals.get("JumpOverLedgeDone"),
        Some(&Value::Number(1.0))
    );
    assert!(!s.program.host.world.frozen);

    // 1. Verify authored Defeat path (Cutscene_PlayerLoses -> PlayEffect(Null) -> LoseMission(196)).
    let checkpoint = (
        s.program.vm.clone(),
        s.program.host.clone(),
        s.scheduler.clone(),
        s.combat.clone(),
    );
    {
        let player = s.program.host.world.player.unwrap();
        s.program.host.world.damage(player, 10_000.0).unwrap();
        for _ in 0..900 {
            s.tick(1.0 / 60.0, Input::default()).unwrap();
            if s.program.host.world.mission_complete.is_some() {
                break;
            }
        }
        assert_eq!(
            s.program.host.world.mission_complete,
            Some(bw_rust::mission_world::MissionOutcome::Lost {
                message_id: Some(196)
            })
        );
    }
    s.program.vm = checkpoint.0;
    s.program.host = checkpoint.1;
    s.scheduler = checkpoint.2;
    s.combat = checkpoint.3;

    // 2. Drive Gameflow_2 to authored Victory (Tower01 -> Cutscene_PlayerWins -> WinMission).
    let mut full_recording = prefix;
    let goals: &[[f64; 2]] = &[
        [65.0, 625.0],  // 0: Drain01 & recruit Sgrunt02..04, open Gates05
        [108.0, 770.0], // 1: Hazard01 & PauseTutorial_SquadAttackDone
        [108.0, 780.0], // 2: Destroy Gate_Winch_Left & Gate_Winch_Right, open Gates02/03
        [65.0, 930.0],  // 3: Send01 & destroy AmmoDump12..14, 20 & clear Blockage
        [-12.3, 894.9], // 4: Hill01 & CombatRollRepeat tutorial
        [-20.1, 842.3], // 5: Middle western road (Hill02)
        [-41.0, 813.5], // 6: Lower western road (Hill03)
        [-51.0, 765.0], // 7: Iron Tower approach
        [-57.8, 745.0], // 8: Inside Tower01 -> WinMission
    ];
    let mut goal_idx = 0usize;
    let mut pause_frames = 0u32;
    let mut planned_goal = None;
    let mut route_points = std::collections::VecDeque::<[f64; 2]>::new();
    let mut last_plan_step = 0usize;
    for step in 0..12_000 {
        let player = s.program.host.world.player.unwrap();
        let pos = s.program.host.positions[&player];
        let paused = s
            .program
            .host
            .world
            .tutorial
            .as_ref()
            .is_some_and(|t| t.paused);
        if paused {
            pause_frames += 1;
        } else {
            pause_frames = 0;
        }
        let confirm = paused && pause_frames >= 125 && pause_frames.is_multiple_of(4);
        let drain_done =
            s.program.vm.globals.get("StaffBearerUnderPlayerCommand") == Some(&Value::Number(1.0));
        let attack_tut_done =
            s.program.vm.globals.get("PauseTutorial_SquadAttackDone") == Some(&Value::Number(2.0));
        let gate_blown = s.program.vm.globals.get("DrainGateBlownUp") == Some(&Value::Number(1.0));
        let blockage_cleared =
            s.program.vm.globals.get("BlockageCleared") == Some(&Value::Number(1.0));

        if goal_idx == 0
            && drain_done
            && s.program.host.world.props[&ObjectId(250012042)].active == Some(false)
        {
            goal_idx = 1;
        } else if goal_idx == 1
            && attack_tut_done
            && !s.program.host.world.props[&ObjectId(250008596)].invulnerable
        {
            goal_idx = 2;
        } else if goal_idx == 2
            && gate_blown
            && s.program.host.world.props[&ObjectId(250012048)].active == Some(false)
            && s.program.host.world.props[&ObjectId(250012040)].active == Some(false)
        {
            goal_idx = 3;
        } else if goal_idx == 3 && blockage_cleared {
            goal_idx = 4;
        } else if goal_idx >= 4 && goal_idx + 1 < goals.len() {
            let g = goals[goal_idx];
            if (pos[0] as f64 - g[0]).hypot(pos[2] as f64 - g[1]) <= 3.0 {
                goal_idx += 1;
            }
        }

        let goal = goals[goal_idx];
        let dist_to_goal = (goal[0] - pos[0] as f64).hypot(goal[1] - pos[2] as f64);
        let hold_here = (goal_idx == 0
            && (!drain_done
                || s.program.host.world.props[&ObjectId(250012042)].active != Some(false)))
            || (goal_idx == 1
                && (!attack_tut_done
                    || s.program.host.world.props[&ObjectId(250008596)].invulnerable))
            || (goal_idx == 2
                && (!gate_blown
                    || s.program.host.world.props[&ObjectId(250012048)].active != Some(false)
                    || s.program.host.world.props[&ObjectId(250012040)].active != Some(false)))
            || (goal_idx == 3 && !blockage_cleared);
        let waiting_at_goal = hold_here && dist_to_goal <= 3.0;

        if !paused
            && !s.program.host.world.frozen
            && !waiting_at_goal
            && (planned_goal != Some(goal) || step - last_plan_step >= 90)
        {
            let h = &s.program.host;
            let scene = h.world.collision.as_ref().unwrap();
            let others: Vec<_> = h
                .world
                .units
                .iter()
                .filter(|(id, u)| {
                    **id != player
                        && !h.world.roster.contains(id)
                        && u.active == Some(true)
                        && u.health > 0.0
                        && !h.world.non_ground_units.contains(id)
                })
                .map(|(id, _)| bw_rust::unit_collision::Other {
                    position: h.positions[id],
                    body: h.world.bodies[id],
                })
                .collect();
            let plan = bw_rust::navigation::plan(
                scene,
                pos,
                goal,
                2.0,
                bw_rust::unit_collision::Body::INFANTRY,
                &others,
                bw_rust::navigation::Limits {
                    expansions: 16384,
                    probes: 524288,
                    extent: 512,
                },
            )
            .unwrap();
            println!(
                "GAMEFLOW2_PLAN step={step} goal_idx={goal_idx} from=({:.1}, {:.1}) to={goal:?} status={:?} pts={}",
                pos[0],
                pos[2],
                plan.status,
                plan.points.len()
            );
            route_points = plan.points.into();
            planned_goal = Some(goal);
            last_plan_step = step;
        }
        while let Some(&pt) = route_points.front() {
            if (pt[0] - pos[0] as f64).hypot(pt[1] - pos[2] as f64) < 1.2 {
                route_points.pop_front();
            } else {
                break;
            }
        }
        let next_pt = route_points.front().copied().unwrap_or(goal);
        let dx = next_pt[0] - pos[0] as f64;
        let dz = next_pt[1] - pos[2] as f64;
        let dist = dx.hypot(dz);

        let (enemy_threat, need_recall, wait_for_vanguard) = if goal_idx >= 4 {
            let h = &s.program.host;
            let squad: Vec<(ObjectId, [f32; 3])> = h
                .world
                .roster
                .iter()
                .filter(|&&id| {
                    id != player
                        && h.world
                            .units
                            .get(&id)
                            .is_some_and(|u| u.active == Some(true) && u.health > 0.0)
                })
                .map(|&id| (id, h.positions[&id]))
                .collect();
            let min_enemy_z = if goal_idx == 4 {
                855.0
            } else {
                f32::NEG_INFINITY
            };
            let threat_p_dist = if goal_idx == 4 { 74.0 } else { 55.0 };
            let threat_q_dist = 50.0;
            let enemy_threat = !squad.is_empty()
                && h.world
                    .units
                    .iter()
                    .filter(|(id, u)| {
                        u.army != h.world.units[&player].army
                            && u.army != "eNoArmy"
                            && u.active == Some(true)
                            && u.health > 0.0
                            && h.world.bodies.contains_key(id)
                            && !h.world.non_ground_units.contains(id)
                    })
                    .any(|(id, _)| {
                        let ep = h.positions[id];
                        if ep[2] < min_enemy_z {
                            return false;
                        }
                        let p_dist = (ep[0] - pos[0]).hypot(ep[2] - pos[2]) as f64;
                        p_dist <= threat_p_dist
                            || squad.iter().any(|(_, q)| {
                                ((ep[0] - q[0]).hypot(ep[2] - q[2]) as f64) <= threat_q_dist
                            })
                    });
            let enemy_close_to_player = !squad.is_empty()
                && h.world
                    .units
                    .iter()
                    .filter(|(id, u)| {
                        u.army != h.world.units[&player].army
                            && u.army != "eNoArmy"
                            && u.active == Some(true)
                            && u.health > 0.0
                            && h.world.bodies.contains_key(id)
                            && !h.world.non_ground_units.contains(id)
                    })
                    .any(|(id, _)| {
                        let ep = h.positions[id];
                        ep[2] >= min_enemy_z && (ep[0] - pos[0]).hypot(ep[2] - pos[2]) <= 45.0
                    });
            let min_squad_dist = squad
                .iter()
                .map(|(_, q)| (q[0] - pos[0]).hypot(q[2] - pos[2]))
                .fold(f32::INFINITY, f32::min);
            let need_recall = !enemy_threat
                && squad
                    .iter()
                    .any(|(id, _)| !h.world.squad_follow.contains(id));
            let lagging = goal_idx == 4
                && !enemy_threat
                && squad
                    .iter()
                    .any(|(_, q)| (q[0] - pos[0]).hypot(q[2] - pos[2]) > 14.0);
            let wait_for_vanguard = goal_idx == 4
                && (enemy_close_to_player || (enemy_threat && min_squad_dist < 24.0) || lagging);
            (enemy_threat, need_recall, wait_for_vanguard)
        } else {
            (false, false, false)
        };

        let mut input = Input {
            confirm,
            recruit: (goal_idx == 0 && !drain_done && step.is_multiple_of(10)) || need_recall,
            send: enemy_threat && step.is_multiple_of(20),
            ..Input::default()
        };
        if !paused && !s.program.host.world.frozen && !waiting_at_goal && dist > 0.5 {
            let aim = s.program.host.world.player_aim.unwrap();
            let current_yaw = aim[0].atan2(aim[2]);
            let desired_yaw = dx.atan2(dz);
            let mut diff = (desired_yaw - current_yaw + std::f64::consts::PI)
                .rem_euclid(std::f64::consts::TAU)
                - std::f64::consts::PI;
            diff = diff.clamp(-0.12, 0.12);
            input.look = [diff, 0.0];
            if diff.abs() < 0.35 && !wait_for_vanguard {
                input.movement = [0.0, 1.0];
            }
        }
        s.tick(1.0 / 60.0, input).unwrap();
        full_recording.push(input);
        if step.is_multiple_of(300)
            || s.program.vm.globals.get("MissionOver") == Some(&Value::Number(1.0))
        {
            let squad_info: Vec<String> = s
                .program
                .host
                .world
                .roster
                .iter()
                .filter(|&&id| id != player)
                .map(|id| {
                    let q = s.program.host.positions[id];
                    let u = &s.program.host.world.units[id];
                    format!("{}:({:.1},{:.1},hp={:.0})", id.0, q[0], q[2], u.health)
                })
                .collect();
            let enemy_info: Vec<String> = s
                .program
                .host
                .world
                .units
                .iter()
                .filter(|(id, u)| {
                    u.army != s.program.host.world.units[&player].army
                        && u.army != "eNoArmy"
                        && u.active == Some(true)
                        && u.health > 0.0
                        && s.program.host.world.bodies.contains_key(id)
                        && !s.program.host.world.non_ground_units.contains(id)
                })
                .map(|(id, u)| {
                    let ep = s.program.host.positions[id];
                    format!("{}:({:.1},{:.1},hp={:.0})", id.0, ep[0], ep[2], u.health)
                })
                .collect();
            println!(
                "step={step} goal={goal_idx} pos=({:.1}, {:.1}) hp={:.0} squad={squad_info:?} enemies={enemy_info:?} drain={drain_done} gate={gate_blown} block={blockage_cleared} over={:?} complete={:?}",
                pos[0],
                pos[2],
                s.program.host.world.units[&player].health,
                s.program.vm.globals.get("MissionOver"),
                s.program.host.world.mission_complete
            );
        }
        if s.program.host.world.mission_complete.is_some() {
            println!(
                "VICTORY at step={step} frame={} outcome={:?}",
                s.program.host.frame, s.program.host.world.mission_complete
            );
            break;
        }
    }
    assert!(
        matches!(
            s.program.host.world.mission_complete,
            Some(bw_rust::mission_world::MissionOutcome::Won { .. })
        ),
        "Expected MissionOutcome::Won, got {:?}",
        s.program.host.world.mission_complete
    );
    assert_eq!(
        s.program
            .host
            .world
            .mission_history
            .as_ref()
            .map(|h| h.completed),
        Some(true)
    );
    std::fs::write(
        root.join("local/analysis/first-victory-inputs.json"),
        serde_json::to_vec(&full_recording).unwrap(),
    )
    .unwrap();
}
